<?php
declare(strict_types=1);
namespace EasyIT\LicenseServer\Customer;
use EasyIT\LicenseServer\Service\AuditService;
use PDO;
final class CustomerAuth{
 private array $cfg;
 public function __construct(private PDO $pdo,private AuditService $audit,array $appCfg=[]){$this->cfg=$appCfg['customer_portal']??[];$this->cfg+=['session_name'=>'EASYITLICCUSTOMER','idle_timeout_seconds'=>1800,'max_failed_logins'=>5,'lock_seconds'=>900];}
 public function startSession():void{if(session_status()===PHP_SESSION_ACTIVE)return;session_name((string)$this->cfg['session_name']);$secure=(!empty($_SERVER['HTTPS'])&&strtolower((string)$_SERVER['HTTPS'])!=='off')||((string)($_SERVER['SERVER_PORT']??'')==='443');session_set_cookie_params(['lifetime'=>0,'path'=>'/','secure'=>$secure,'httponly'=>true,'samesite'=>'Strict']);ini_set('session.use_only_cookies','1');ini_set('session.use_strict_mode','1');session_start();if(empty($_SESSION['customer_csrf']))$_SESSION['customer_csrf']=bin2hex(random_bytes(32));}
 public function login(string $username,string $password):bool{$st=$this->pdo->prepare('SELECT u.*,c.status customer_status FROM customer_users u JOIN customers c ON c.customer_id=u.customer_id WHERE u.username=? LIMIT 1');$st->execute([trim($username)]);$r=$st->fetch();$now=time();if(!$r){password_verify($password,'$2y$10$3NQ2k.5H0X7gYPQLWspvMO6vhkcwuPd0szC4yR9QkwpJ9cAtx9iD2');return false;}if((string)$r['status']!=='active'||(string)$r['customer_status']!=='active')return false;if(!empty($r['locked_until'])&&$now<(int)$r['locked_until'])return false;if(!password_verify($password,(string)$r['password_hash'])){$f=(int)$r['failed_attempts']+1;$locked=null;if($f>=(int)$this->cfg['max_failed_logins']){$locked=$now+(int)$this->cfg['lock_seconds'];$f=0;}$this->pdo->prepare('UPDATE customer_users SET failed_attempts=?,locked_until=?,updated_at=? WHERE customer_user_id=?')->execute([$f,$locked,$now,$r['customer_user_id']]);$this->audit->write('CUSTOMER_LOGIN_FAILED','customer_user',(string)$r['customer_user_id'],'customer_user',(string)$r['customer_user_id']);return false;}session_regenerate_id(true);$_SESSION['customer_user']=['id'=>(string)$r['customer_user_id'],'customer_id'=>(string)$r['customer_id'],'username'=>(string)$r['username'],'display_name'=>(string)$r['display_name'],'role'=>(string)$r['role'],'credential_version'=>(int)($r['credential_version']??1)];$_SESSION['customer_last_activity']=$now;$_SESSION['customer_csrf']=bin2hex(random_bytes(32));$this->pdo->prepare('UPDATE customer_users SET failed_attempts=0,locked_until=NULL,last_login_at=?,updated_at=? WHERE customer_user_id=?')->execute([$now,$now,$r['customer_user_id']]);$this->audit->write('CUSTOMER_LOGIN','customer_user',(string)$r['customer_user_id'],'customer_user',(string)$r['customer_user_id']);return true;}
 public function user():?array{$u=$_SESSION['customer_user']??null;if(!is_array($u))return null;$now=time();$last=(int)($_SESSION['customer_last_activity']??0);if($last>0&&$now-$last>(int)$this->cfg['idle_timeout_seconds']){$this->logout();return null;}$st=$this->pdo->prepare('SELECT u.status,u.credential_version,c.status customer_status FROM customer_users u JOIN customers c ON c.customer_id=u.customer_id WHERE u.customer_user_id=? LIMIT 1');$st->execute([(string)$u['id']]);$r=$st->fetch();if(!$r||(string)$r['status']!=='active'||(string)$r['customer_status']!=='active'||(int)($r['credential_version']??1)!==(int)($u['credential_version']??1)){$this->logout();return null;}$_SESSION['customer_last_activity']=$now;return$u;}
 public function acceptCredentialVersion(int $version):void{if(isset($_SESSION['customer_user'])&&is_array($_SESSION['customer_user']))$_SESSION['customer_user']['credential_version']=$version;}
 public function logout():void{$u=$_SESSION['customer_user']??null;if(is_array($u))$this->audit->write('CUSTOMER_LOGOUT','customer_user',(string)$u['id'],'customer_user',(string)$u['id']);$_SESSION=[];if(ini_get('session.use_cookies')){$p=session_get_cookie_params();setcookie(session_name(),'',time()-42000,$p['path'],$p['domain']??'',(bool)$p['secure'],(bool)$p['httponly']);}session_destroy();}
 public function csrf():string{return(string)($_SESSION['customer_csrf']??'');}
 public function verifyCsrf(string $v):void{$e=$this->csrf();if($e===''||$v===''||!hash_equals($e,$v))throw new \RuntimeException('CUSTOMER_CSRF_INVALID');}
 public function flash(string $type,string $message):void{$_SESSION['customer_flash'][]=['type'=>$type,'message'=>$message];}
 public function consumeFlash():array{$f=$_SESSION['customer_flash']??[];unset($_SESSION['customer_flash']);return is_array($f)?$f:[];}
}
